"use client";

import type { MotionValue, TargetAndTransition } from "motion/react";
import { motion } from "motion/react";

import { DURATION, EASE } from "@/components/ui/motion";

/*
 * The Why Choose Us card artwork, inlined.
 *
 * These were `next/image` on the six SVGs in public/design/why-us/ until the
 * section was found to be the flattest on the page. The assets were never the
 * problem: Figma's exports already carry their layers as named nodes (`rocket`,
 * `dollar`, `Vector 6674` and so on). The problem was the delivery. An
 * <img src="art.svg"> is ONE opaque box to the DOM — nothing inside it can be
 * addressed, so the sweep and the subject it sits behind can never move
 * independently, at any price. Inlining is what makes the layers reachable, and
 * everything below is spent on that.
 *
 * Three further things fell out of the move, none of them the reason for it:
 *
 *   - the `unoptimized` prop is gone, and with it the trap it guarded. Next's
 *     optimizer refuses SVG unless `dangerouslyAllowSVG` is set (it is not, and
 *     should not be — it would apply to every SVG the app ever serves), so a
 *     dropped `unoptimized` used to 400 the request and blank all six cards.
 *   - art-communication.svg is no longer needed. That file was three base64
 *     <image> blobs stitched together offline because Figma composites that card
 *     through an alpha mask and exports it in pieces. The pieces are inlined
 *     here as real vector instead, at the same card-space coordinates.
 *   - every Figma <mask> is dropped. Each was a 365 x 370 rx=16 rect, which is
 *     exactly the card; the card's own `overflow-hidden rounded-2xl` already
 *     does it, so they were six copies of a clip the layout performs anyway.
 *
 * `preserveAspectRatio="none"` is kept from the exports and is deliberate. The
 * card is aspect-[365/370] so at any normal width the ratio is 1:1 and it never
 * engages; below `min-h-[340px]` on a narrow phone the card gets taller than its
 * ratio and the art stretches to follow, which is what the <img> did before and
 * what keeps the sweep welded to the card's bottom edge.
 *
 * Colours are the exports', untouched: #BCBCBC line art, #FD7C5A / #FF884D
 * sweeps (both oranges are in the design and they are NOT the same value).
 * Nothing here reads currentColor, because nothing here should recolour.
 */

/* Peak parallax drift of the subject against its sweep, in viewBox units. The
 * viewBox is 370 tall against a ~370px card, so a unit is about a px. */
export const ART_DRIFT = 14;

export type WhyUsArtVariant =
  | "customDesign"
  | "affordable"
  | "responsive"
  | "communication"
  | "oneSolution"
  | "fastDelivery";

/*
 * The one entrance, shared by all six cards.
 *
 * The sweep is the only element every card has, so it is what makes the grid
 * read as one section rather than six unrelated boxes: the same ground rises
 * into every card, and the subject settles onto it a beat later. Both are
 * inherited — there is no observer in this file. The labels arrive through
 * MotionContext from the wrapper in WhyUsCard, so a card and its artwork can
 * never fire against each other.
 */
const SWEEP = {
  hidden: { y: 96, opacity: 0 },
  visible: {
    y: 0,
    opacity: 1,
    transition: { duration: DURATION.display, delay: 0.1, ease: EASE },
  },
};

const SUBJECT = {
  hidden: { y: 20, opacity: 0 },
  visible: {
    y: 0,
    opacity: 1,
    transition: { duration: DURATION.content, delay: 0.26, ease: EASE },
  },
};

/* Hover is `.lift`'s curve and duration exactly (globals.css), so the card's
 * raise and whatever moves inside it are one gesture, not two. */
const HOVER = { duration: 0.4, ease: EASE };

/*
 * Rotation and scale on an SVG node need an explicit box to resolve against.
 * `fill-box` is the element's own geometry, so "center" means the centre of the
 * mark itself rather than of the 365 x 370 canvas it happens to sit on — the
 * difference between a sparkle spinning in place and one orbiting the card.
 * Translation does not need this; only the elements that turn or scale carry it.
 */
const PIVOT = { transformBox: "fill-box", transformOrigin: "center" } as const;

const GREY = "#BCBCBC";

/** A layer's resting and hovered pose. One transform property, by convention. */
type HoverPair = { rest: TargetAndTransition; hover: TargetAndTransition };

type ArtProps = {
  variant: WhyUsArtVariant;
  /** Scroll-linked drift, or null under reduced motion. */
  drift: MotionValue<number> | null;
  hovered: boolean;
};

export function WhyUsArt({ variant, drift, hovered }: ArtProps) {
  const still = drift === null;
  const at = hovered ? "hover" : "rest";

  /*
   * Three nested groups, one concern each, because they all write `transform`
   * and the last writer would win if they shared a node:
   *
   *   drift   scroll-linked, a MotionValue in `style`
   *   enter   the reveal, inherited variants
   *   hover   an explicit `animate`, which is also why it must be its own node
   *           — an element with its own `animate` stops inheriting the parent's
   *           variant label, so putting hover on `enter` would cost the entrance
   *
   * Under reduced motion each degrades by having its animation source removed
   * rather than by branching the markup: no style, no variants, and `hovered`
   * arrives already false from the card. The groups stay, inert.
   */
  const subject = (children: React.ReactNode) => (
    <motion.g style={still ? undefined : { y: drift }}>
      <motion.g variants={still ? undefined : SUBJECT}>{children}</motion.g>
    </motion.g>
  );

  const sweep = (children: React.ReactNode) => (
    <motion.g variants={still ? undefined : SWEEP}>{children}</motion.g>
  );

  /** Wraps the layer a card moves on hover. `v` is its rest/hover pair. */
  const grab = (
    v: HoverPair,
    children: React.ReactNode,
    pivot = false,
  ) => (
    <motion.g
      style={pivot ? PIVOT : undefined}
      variants={still ? undefined : { rest: v.rest, hover: v.hover }}
      /* Explicit, so the inherited "hidden" label cannot reach this node and
       * leave it looking for a variant it does not define on mount. */
      initial={false}
      animate={at}
      transition={HOVER}
    >
      {children}
    </motion.g>
  );

  return (
    <svg
      viewBox="0 0 365 370"
      preserveAspectRatio="none"
      fill="none"
      aria-hidden
      className="pointer-events-none absolute inset-0 h-full w-full"
    >
      {ART[variant]({ sweep, subject, grab, still })}
    </svg>
  );
}

type Builders = {
  sweep: (children: React.ReactNode) => React.ReactNode;
  subject: (children: React.ReactNode) => React.ReactNode;
  grab: (
    v: HoverPair,
    children: React.ReactNode,
    pivot?: boolean,
  ) => React.ReactNode;
  still: boolean;
};

/*
 * One builder per card, in the grid's reading order.
 *
 * Paint order is the export's and is load-bearing in two of them: One Solution
 * and Fast Delivery draw the sweep OVER the subject, so the rocket and the
 * sparkle are partly submerged in it. Emitting sweep-then-subject uniformly
 * would lift them out of the ground and lose the design's depth, so each builder
 * emits its layers in the order Figma did.
 *
 * Hover is one transform per layer, always: the six differ in WHAT moves, never
 * in how. Same curve, same duration, same magnitude class throughout — a card
 * that needed two properties to make its point would be the wrong idea for that
 * card, not a reason to spend a second property.
 */
